# Generated by GPT-6.2 Astra
import hashlib
import json
from pathlib import Path

import numpy as np
from PIL import Image, ImageOps

from character_model import DATASET, MODEL56

TRAIN_ARCHIVE = DATASET / "训练集" / "训练扩充.zip"


def read_records(data=DATASET, capture_dir=None):
    records = [
        json.loads(line)
        for line in (data / "样本索引.jsonl").read_text("utf8").splitlines()
    ]
    groups = {}
    for row in records:
        if row["class_id"] not in range(1, 16):
            raise ValueError(f"Invalid role: {row['sample_id']}")
        if groups.setdefault(row["source_group"], row["split"]) != row["split"]:
            raise ValueError(
                f"Artwork appears in multiple splits: {row['source_group']}"
            )
        row["file"] = data / row["path"]
    if capture_dir is None:
        return records
    excluded = {
        r["source_group"]
        for r in json.loads((data / "评测排除.json").read_text("utf8"))
    }
    sessions = {}
    for meta in sorted(Path(capture_dir).rglob("*.json")):
        rec = json.loads(meta.read_text("utf8"))
        if rec.get("format") != "NPU4-RGB565-LE" or rec.get("split") == "demo":
            continue
        if rec.get("label") not in range(1, 16):
            continue
        part, group, session = (
            rec["split"],
            rec["source_group"].strip(),
            rec["session"].strip(),
        )
        if part not in ("train", "val", "test") or not group or not session:
            raise ValueError(f"Incomplete capture metadata: {meta}")
        if rec.get("origin") not in ("fpga", "webcam"):
            raise ValueError(f"Invalid camera origin: {meta}")
        if part in ("val", "test") and (
            group in excluded or rec.get("subject_origin") != "actual"
        ):
            if (
                group in excluded
                or "subject_origin" in rec
                or groups.get(group) != part
            ):
                raise ValueError(
                    f"Evaluation requires a genuine, eligible source: {meta}"
                )
        if (
            groups.setdefault(group, part) != part
            or sessions.setdefault(session, part) != part
        ):
            raise ValueError(f"Capture crosses an artwork or session split: {meta}")
        source = meta.with_suffix(".rgb565")
        raw = source.read_bytes()
        if len(raw) != 2 * 56 * 56:
            raise ValueError(f"Incomplete RGB565 capture: {source}")
        records.append(
            dict(
                sample_id=meta.stem,
                class_id=int(rec["label"]),
                kind="camera",
                split=part,
                source_group=group,
                session=session,
                file=source,
                sha256=hashlib.sha256(raw).hexdigest(),
            )
        )
    return records


def frozen_rows():
    rows = read_records()
    manifest = json.loads((MODEL56 / "splits.json").read_text("utf8"))
    frozen = {r["sample_id"]: r for r in manifest}
    if len(rows) != len(manifest) or {r["sample_id"] for r in rows} != set(frozen):
        raise ValueError("Dataset differs from the frozen split")
    blocked = {
        r["source_group"]
        for r in json.loads((DATASET / "评测排除.json").read_text("utf8"))
    }
    real = {
        "web_image",
        "web_motion_poster",
        "web_cover_crop",
        "gif_frame",
        "video_frame",
        "verified_video_frame",
        "camera",
    }
    splits = {}
    for row in rows:
        original = frozen[row["sample_id"]]
        if any(original[k] != row[k] for k in original):
            raise ValueError(f"Changed split or label: {row['sample_id']}")
        sha = hashlib.sha256(row["file"].read_bytes()).hexdigest()
        if sha != row["sha256"] or splits.setdefault(sha, row["split"]) != row["split"]:
            raise ValueError(f"Image changed or crossed split: {row['sample_id']}")
        if row["split"] != "train" and (
            row["kind"] not in real or row["source_group"] in blocked
        ):
            raise ValueError(f"Ineligible held-out image: {row['sample_id']}")
    return rows


def training_members(archive, rows):
    parents = {r["sample_id"]: r for r in rows if r["split"] == "train"}
    held_out = {r["sha256"] for r in rows if r["split"] in ("val", "test")}
    for pose in json.loads(archive.read("画稿来源.json")):
        ref = parents[pose["reference"]]
        if ref["kind"] != "reference" or any(
            pose[k] != ref[k] for k in ("class_id", "source_group")
        ):
            raise ValueError(f"Invalid source for generated pose: {pose['sample_id']}")
        parents[pose["sample_id"]] = pose
    members = [json.loads(line) for line in archive.read("样本索引.jsonl").splitlines()]
    paths = {r["path"] for r in members}
    files = [p for p in archive.namelist() if p.endswith(".png")]
    if len(members) != len(paths) or len(files) != len(paths) or set(files) != paths:
        raise ValueError("Training PNGs differ from their catalogue")
    for row in members:
        parent = parents[row["parent"]]
        if (
            row["split"] != "train"
            or row["sha256"] in held_out
            or any(row[k] != parent[k] for k in ("class_id", "source_group"))
        ):
            raise ValueError(
                f"Training image crosses an artwork or class: {row['path']}"
            )
    return members


def read_variant(archive, member):
    raw = archive.read(member["path"])
    if hashlib.sha256(raw).hexdigest() != member["sha256"]:
        raise ValueError(f"Training image checksum mismatch: {member['path']}")
    return raw


def card(path):
    with Image.open(path) as image:
        rgba = ImageOps.exif_transpose(image).convert("RGBA")
        rgba.thumbnail((180, 180), Image.Resampling.LANCZOS)
        size = tuple(max(1, round(n * 180 / max(rgba.size))) for n in rgba.size)
        rgba = rgba.resize(size, Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (224, 224), "white")
        canvas.paste(
            rgba, ((224 - size[0]) // 2, (224 - size[1]) // 2), rgba.getchannel("A")
        )
    return np.asarray(canvas)
